style.css:
@-moz-document domain("codehs.com") {
body {
    background-color: #ffe4f0 !important;  /* soft pastel pink */
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    color: #4b0033 !important; /* dark pink text for readability */
  }
  /* Hide right sidebar (adjust class name if needed) */
  .sidebar-right, .some-sidebar-class {
    display: none !important;
  }
  /* Make main content wider */
  .main-content {
    width: 90% !important;
  }
  /* Change links to a brighter pink */
  a {
    color: #ff4081 !important;
  }
  /* Buttons with pink background */
  button, .btn {
    background-color: #ff66a3 !important;
    color: white !important;
    border: none !important;
    border-radius: 5px !important;
  }
}
